class IdempotencyCreateRaceException : RuntimeException()

@Service class MateService(private val posts:MatePostRepository, private val participations:MateParticipationRepository, private val sports:SportRepository, private val regions:RegionRepository, private val keys:IdempotencyKeyRepository, private val notifications:NotificationWriter, private val clock:Clock, private val rooms:MateChatRoomRepository, private val profiles:UserProfileRepository, private val objectMapper:ObjectMapper, private val access:MateAccessPolicy) {
 @Transactional(readOnly=true) fun list(viewer:UUID,sportCode:String?,regionId:UUID?,from:Instant?,to:Instant?,difficulty:MateDifficulty?,status:MatePostStatus?,cursor:String?,size:Int):CursorPageResponse<MatePostResponse>{
  val boundary=decodeCursor(cursor); val limit=size.coerceIn(1,100)
  val selected=posts.findPage(sportCode,regionId?.let(::db),from,to,difficulty,status,boundary?.first,boundary?.second,PageRequest.of(0,limit+1),viewer)
  val hasNext=selected.size>limit; val values=selected.take(limit); return CursorPageResponse(values.map(::response),if(hasNext) encodeCursor(values.last().createdAt,requireNotNull(values.last().id)) else null,hasNext)
 }
 @Transactional(readOnly=true) fun get(id:UUID)=response(post(id))
 @Transactional(readOnly=true) fun detail(user:UUID,id:UUID):MatePostDetailResponse { val p=post(id); access.requireVisible(p,user); val mine=participations.findByPostIdAndUserId(requireNotNull(p.id),user)?.let(::app); val roomId=rooms.findByPostIdAndInquirerId(requireNotNull(p.id),user)?.id; val author=requireNotNull(p.authorId); val nickname=profiles.findById(author).orElse(null)?.nickname; val actions=mutableSetOf<String>(); if(author==user) { actions.addAll(setOf("UPDATE","CLOSE","CANCEL","VIEW_APPLICATIONS")) } else if(p.status==MatePostStatus.RECRUITING&&p.scheduledStartAt>clock.instant()) { if(mine==null) actions.add("APPLY"); if(roomId==null) actions.add("OPEN_INQUIRY_ROOM") }; return MatePostDetailResponse(requireNotNull(p.id),author,nickname,MateUserSummary(author,nickname),p.sport?.code?.name?:"",UuidBinaryConverter.fromMysqlOrderedUuid(requireNotNull(p.region?.id)),p.title,p.body,p.scheduledStartAt,p.durationSeconds,p.locationSummary,p.capacity,p.difficulty,p.estimatedCostKrw,p.acceptedCount,p.capacity-p.acceptedCount,p.status,p.version,p.createdAt,p.updatedAt,mine,roomId,actions,if(p.status!=MatePostStatus.CANCELED&&(author==user||mine?.status==MateParticipationStatus.ACCEPTED))p.meetingPoint else null,p.visibility,fields(p),p.beginnerWelcome) }
 @Transactional fun create(user:UUID,key:UUID,r:CreateMatePostRequest):MatePostResponse {
  val hash=hash(r); keys.findByUserIdAndIdempotencyKey(user,key)?.let { existing -> if(existing.expiresAt>clock.instant()) { if(existing.requestHash!=hash) throw ApiException(ApiErrorCode.IDEMPOTENCY_KEY_CONFLICT); return replay(existing) }; keys.delete(existing); keys.flush() }
  if(r.scheduledStartAt<=clock.instant()) bad("시작 시각은 현재 이후여야 합니다.")
  val sport=sports.findByCodeAndIsActiveTrue(runCatching { SportCode.valueOf(r.sportCode) }.getOrElse { bad("지원하지 않는 종목입니다.") })?:bad("활성 종목이 아닙니다.")
  val region=regions.findById(db(r.regionId)).orElseThrow { ApiException(ApiErrorCode.RESOURCE_NOT_FOUND) }
  val p=posts.saveAndFlush(MatePost(UUID.randomUUID(),user,sport,region,r.title.trim(),r.body.trim(),r.scheduledStartAt,r.durationSeconds,r.locationSummary.trim(),r.capacity,1,r.difficulty,r.estimatedCostKrw,meetingPoint=r.meetingPoint?.trim()?.takeIf{it.isNotEmpty()},visibility=r.visibility,sportFields=encodeFields(r.sportFields),beginnerWelcome=r.beginnerWelcome))
  participations.save(MateParticipation(UUID.randomUUID(),p,user,MateParticipantRole.HOST,MateParticipationStatus.ACCEPTED,appliedAt=clock.instant(),respondedAt=clock.instant()))
  val response=response(p)
  try { keys.saveAndFlush(IdempotencyKeyRecord(UUID.randomUUID(),user,key,hash,201,objectMapper.writeValueAsString(response),clock.instant().plus(Duration.ofDays(1)))) } catch(_:org.springframework.dao.DataIntegrityViolationException) { throw IdempotencyCreateRaceException() }
  return response
 }
 @Transactional fun update(user:UUID,id:UUID,r:UpdateMatePostRequest):MatePostResponse { val p=locked(id); owner(p,user); version(p.version,r.version); if(p.status !in setOf(MatePostStatus.RECRUITING,MatePostStatus.FULL)) throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION); val restricted=r.sportCode!=null||r.regionId!=null||r.scheduledStartAt!=null||r.durationSeconds!=null||r.locationSummary!=null||r.difficulty!=null||r.estimatedCostKrw!=null||r.meetingPoint!=null||r.visibility!=null||r.sportFields!=null||r.beginnerWelcome!=null; if(restricted&&participations.findAllByPostId(requireNotNull(p.id)).any{it.role==MateParticipantRole.MEMBER})throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION); r.meetingPoint?.let{p.meetingPoint=it.trim().takeIf{v->v.isNotEmpty()}};r.visibility?.let{p.visibility=it};r.sportFields?.let{p.sportFields=encodeFields(it)};r.beginnerWelcome?.let{p.beginnerWelcome=it};r.sportCode?.let{code->p.sport=sports.findByCodeAndIsActiveTrue(runCatching { SportCode.valueOf(code) }.getOrElse { bad("지원하지 않는 종목입니다.") })?:bad("활성 종목이 아닙니다.")};r.regionId?.let{p.region=regions.findById(db(it)).orElseThrow { ApiException(ApiErrorCode.RESOURCE_NOT_FOUND) }};r.scheduledStartAt?.let{if(it<=clock.instant())bad("시작 시각은 현재 이후여야 합니다.");p.scheduledStartAt=it};r.durationSeconds?.let{p.durationSeconds=it};r.locationSummary?.let{p.locationSummary=nonblank(it)};r.difficulty?.let{p.difficulty=it};r.estimatedCostKrw?.let{p.estimatedCostKrw=it};r.title?.let{p.title=nonblank(it)};r.body?.let{p.body=nonblank(it)};r.capacity?.let{if(it<p.acceptedCount) bad("수락 인원보다 작게 정원을 변경할 수 없습니다.");p.capacity=it;p.status=if(it==p.acceptedCount) MatePostStatus.FULL else MatePostStatus.RECRUITING}; posts.flush(); return response(p) }
 @Transactional fun apply(user:UUID,id:UUID):MateApplicationResponse { val p=locked(id); access.requireVisible(p,user); open(p);if(p.authorId==user) bad("작성자는 신청할 수 없습니다.");if(participations.findByPostIdAndUserId(requireNotNull(p.id),user)!=null) throw ApiException(ApiErrorCode.MATE_APPLICATION_ALREADY_EXISTS);val a=participations.save(MateParticipation(UUID.randomUUID(),p,user,MateParticipantRole.MEMBER,MateParticipationStatus.PENDING,appliedAt=clock.instant()));notifications.mate(requireNotNull(p.authorId),user,"MATE_APPLICATION_RECEIVED","mate_application_received:${requireNotNull(a.id)}","{\"postId\":\"${requireNotNull(p.id)}\"}");participations.flush();return app(a) }
 @Transactional fun decide(user:UUID,postId:UUID,id:UUID,version:Long,accept:Boolean):MateApplicationResponse { val p=locked(postId);owner(p,user);open(p);val a=application(p,id);version(a.version,version);if(a.status!=MateParticipationStatus.PENDING) throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);if(accept){if(p.acceptedCount>=p.capacity)throw ApiException(ApiErrorCode.MATE_CAPACITY_EXCEEDED);a.status=MateParticipationStatus.ACCEPTED;p.acceptedCount++;if(p.acceptedCount==p.capacity)p.status=MatePostStatus.FULL}else{a.status=MateParticipationStatus.REJECTED};a.respondedAt=clock.instant();notifications.mate(requireNotNull(a.userId),user,"MATE_APPLICATION_${a.status}","mate_application:${requireNotNull(a.id)}:${a.status}","{\"postId\":\"${requireNotNull(p.id)}\"}");participations.flush();return app(a) }
 @Transactional fun withdraw(user:UUID,postId:UUID,id:UUID,version:Long):MateApplicationResponse { val p=locked(postId);val a=application(p,id);if(a.userId!=user)throw ApiException(ApiErrorCode.RESOURCE_NOT_FOUND);version(a.version,version);if(a.status !in setOf(MateParticipationStatus.PENDING,MateParticipationStatus.ACCEPTED))throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);val old=a.status;a.status=if(old==MateParticipationStatus.PENDING)MateParticipationStatus.CANCELED else MateParticipationStatus.WITHDRAWN;a.canceledAt=clock.instant();if(old==MateParticipationStatus.ACCEPTED){p.acceptedCount--;if(p.status==MatePostStatus.FULL&&p.scheduledStartAt>clock.instant())p.status=MatePostStatus.RECRUITING};notifications.mate(requireNotNull(p.authorId),user,"MATE_PARTICIPATION_${a.status}","mate_participation:${requireNotNull(a.id)}:${a.status}","{\"postId\":\"${requireNotNull(p.id)}\"}");participations.flush();return app(a) }
 @Transactional fun close(user:UUID,id:UUID,v:Long):MatePostResponse {val p=locked(id);owner(p,user);version(p.version,v);if(p.status !in setOf(MatePostStatus.RECRUITING,MatePostStatus.FULL))throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);val recipients=recipients(p,setOf(MateParticipationStatus.PENDING,MateParticipationStatus.ACCEPTED));p.status=MatePostStatus.CLOSED;p.closedAt=clock.instant();participations.findAllByPostId(requireNotNull(p.id)).filter{it.role==MateParticipantRole.MEMBER&&it.status==MateParticipationStatus.PENDING}.forEach{it.status=MateParticipationStatus.CANCELED;it.statusReason="POST_CLOSED"};recipients.forEach{notifications.mate(it,user,"MATE_POST_CLOSED","mate_post_closed:${requireNotNull(p.id)}:$it","{\"postId\":\"${requireNotNull(p.id)}\"}")};posts.flush();return response(p)}
 @Transactional fun cancel(user:UUID,id:UUID,v:Long):MatePostResponse {val p=locked(id);owner(p,user);version(p.version,v);if(p.status==MatePostStatus.CANCELED)throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);val recipients=recipients(p,setOf(MateParticipationStatus.PENDING,MateParticipationStatus.ACCEPTED));p.status=MatePostStatus.CANCELED;p.canceledAt=clock.instant();participations.findAllByPostId(requireNotNull(p.id)).filter{it.role==MateParticipantRole.MEMBER&&it.status in setOf(MateParticipationStatus.PENDING,MateParticipationStatus.ACCEPTED)}.forEach{it.status=MateParticipationStatus.CANCELED;it.statusReason="POST_CANCELED"};recipients.forEach{notifications.mate(it,user,"MATE_POST_CANCELED","mate_post_canceled:${requireNotNull(p.id)}:$it","{\"postId\":\"${requireNotNull(p.id)}\"}")};posts.flush();return response(p)}
 @Transactional(readOnly=true) fun applications(user:UUID,id:UUID,status:MateParticipationStatus?,cursor:String?,size:Int):CursorPageResponse<MateApplicationResponse>{val p=post(id);owner(p,user);val boundary=decodeCursor(cursor);val limit=size.coerceIn(1,100);val selected=participations.findPageByPostId(requireNotNull(p.id),status,boundary?.first,boundary?.second,PageRequest.of(0,limit+1));val hasNext=selected.size>limit;val values=selected.take(limit);return CursorPageResponse(values.map(::app),if(hasNext)encodeCursor(values.last().createdAt,requireNotNull(values.last().id))else null,hasNext)}
 @Transactional(readOnly=true) fun myApplication(user:UUID,id:UUID):MateApplicationResponse? { val p=post(id); access.requireVisible(p,user); return participations.findByPostIdAndUserId(requireNotNull(p.id),user)?.let(::app) }
 @Transactional(readOnly=true, propagation=Propagation.REQUIRES_NEW) fun replayCreate(user:UUID,key:UUID,r:CreateMatePostRequest):MatePostResponse { val saved=keys.findByUserIdAndIdempotencyKey(user,key)?:throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);if(saved.expiresAt<=clock.instant())throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);if(saved.requestHash!=hash(r))throw ApiException(ApiErrorCode.IDEMPOTENCY_KEY_CONFLICT);return replay(saved) }
 private fun encodeFields(values:Map<String,String>):String {
  if(values.size>20||values.any{(key,value)->key.isBlank()||key.length>80||value.length>500})bad("상세 조건은 20개 이하, 항목명 80자·값 500자 이내로 입력하세요.")
  return objectMapper.writeValueAsString(values.toSortedMap())
 }
 private fun fields(p:MatePost):Map<String,String> = objectMapper.readValue(p.sportFields,object:com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>() {})
 private fun locked(id:UUID)=posts.findLocked(id)?:throw ApiException(ApiErrorCode.RESOURCE_NOT_FOUND); private fun post(id:UUID)=posts.findById(id).orElseThrow{ApiException(ApiErrorCode.RESOURCE_NOT_FOUND)};private fun application(p:MatePost,id:UUID)=participations.findById(id).orElseThrow{ApiException(ApiErrorCode.RESOURCE_NOT_FOUND)}.also{if(it.post?.id!=p.id)throw ApiException(ApiErrorCode.RESOURCE_NOT_FOUND)};private fun owner(p:MatePost,u:UUID){if(p.authorId!=u)throw ApiException(ApiErrorCode.FORBIDDEN_RESOURCE)};private fun open(p:MatePost){if(p.status!=MatePostStatus.RECRUITING||p.scheduledStartAt<=clock.instant())throw ApiException(ApiErrorCode.MATE_POST_NOT_RECRUITING)};private fun version(a:Long,b:Long){if(a!=b)throw ApiException(ApiErrorCode.VERSION_CONFLICT)};private fun nonblank(s:String)=s.trim().takeIf{it.isNotEmpty()}?:bad("공백만 입력할 수 없습니다.");private fun bad(s:String):Nothing=throw ApiException(ApiErrorCode.VALIDATION_ERROR,s);private fun db(x:UUID)=UuidBinaryConverter.toMysqlOrderedUuid(x);private fun decodeCursor(value:String?):Pair<Instant,UUID>?=value?.let{runCatching{String(java.util.Base64.getUrlDecoder().decode(it)).split('|').let{parts->Instant.ofEpochMilli(parts[0].toLong()) to UUID.fromString(parts[1])}}.getOrElse{throw ApiException(ApiErrorCode.VALIDATION_ERROR,"cursor가 올바르지 않습니다.")}};private fun encodeCursor(at:Instant,id:UUID)=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString("${at.toEpochMilli()}|$id".toByteArray());private fun hash(r:CreateMatePostRequest)=MessageDigest.getInstance("SHA-256").digest(listOf(r.title.trim(),r.body.trim(),r.sportCode.trim(),r.regionId.toString(),r.scheduledStartAt.toString(),r.durationSeconds?.toString().orEmpty(),r.locationSummary.trim(),r.capacity.toString(),r.difficulty.name,r.estimatedCostKrw?.toString().orEmpty(),r.meetingPoint?.trim().orEmpty(),r.visibility.name,encodeFields(r.sportFields),r.beginnerWelcome.toString()).joinToString("\n").toByteArray()).joinToString(""){"%02x".format(it)};private fun replay(saved:IdempotencyKeyRecord):MatePostResponse=runCatching{objectMapper.readValue(requireNotNull(saved.responseBody),MatePostResponse::class.java)}.getOrElse{val postId=Regex("\\\"postId\\\"\\s*:\\s*\\\"([^\\\"]+)\\\"").find(saved.responseBody ?: "")?.groupValues?.get(1)?.let(UUID::fromString)?:throw ApiException(ApiErrorCode.INVALID_STATE_TRANSITION);get(postId)};private fun recipients(p:MatePost,statuses:Set<MateParticipationStatus>): Set<UUID> = (participations.findAllByPostId(requireNotNull(p.id)).filter{it.role==MateParticipantRole.MEMBER&&it.status in statuses}.mapNotNull{it.userId}+rooms.findAllByPostId(requireNotNull(p.id)).mapNotNull{it.inquirerId}).toSet();private fun response(p:MatePost):MatePostResponse{val author=requireNotNull(p.authorId);val nickname=profiles.findById(author).orElse(null)?.nickname;return MatePostResponse(requireNotNull(p.id),author,MateUserSummary(author,nickname),p.sport?.code?.name?:"",UuidBinaryConverter.fromMysqlOrderedUuid(requireNotNull(p.region?.id)),p.title,p.body,p.scheduledStartAt,p.durationSeconds,p.locationSummary,p.capacity,p.difficulty,p.estimatedCostKrw,p.acceptedCount,p.capacity-p.acceptedCount,p.status,p.version,p.createdAt,p.updatedAt,p.visibility,fields(p),p.beginnerWelcome)};private fun app(a:MateParticipation):MateApplicationResponse{val user=requireNotNull(a.userId);val nickname=profiles.findById(user).orElse(null)?.nickname;val post=requireNotNull(a.post);return MateApplicationResponse(requireNotNull(a.id),requireNotNull(post.id),user,MateUserSummary(user,nickname),a.status,a.statusReason,post.status,post.acceptedCount,a.appliedAt,a.respondedAt,a.canceledAt,a.version)}
}
